"""A food web generated by the niche model (Williams and Martinez 2000).

S = 30 species, target connectance C = 0.12. Each species i has a niche value n_i ~ U(0, 1), a feeding
range r_i = x n_i with x ~ Beta(1, beta), beta = 1/(2C) - 1 (so that E[x] = 2C), and a range centre
c_i ~ U(r_i/2, n_i); it eats every species whose niche value lies in [c_i - r_i/2, c_i + r_i/2].
The species with the smallest niche value is made basal (r = 0). Webs with isolated species are
redrawn. Trophic levels are prey-averaged: TL_i = 1 for species without prey and
TL_i = 1 + (1/k_i) sum_{j in prey(i)} TL_j otherwise (k_i prey, cannibalistic links ignored), obtained by
solving the linear system (I - Q) TL = 1, Q the diet-fraction matrix.
A: the web, species placed by niche value (x) and trophic level (y); lines run from prey to consumer.
B: the feeding matrix (consumers as rows, resources as columns, both ordered by niche value): each
diet is a contiguous interval, the defining property of the model.
"""

import numpy as np

import wikibio as bio
from wikibio import charts as C
from wikibio import quant as Q

P = bio.P
FS = bio.core.FONT
rng = np.random.default_rng(4)
fig, ax = bio.canvas(30.0, 13.0)

S, Ct = 30, 0.12


def niche_web():
    while True:
        n = np.sort(rng.random(S))
        x = rng.beta(1, 1 / (2 * Ct) - 1, S)
        r = x * n
        r[0] = 0
        c = rng.uniform(r / 2, n)
        A = (n[None, :] >= (c - r / 2)[:, None]) & (n[None, :] <= (c + r / 2)[:, None])  # A[i, j]: i eats j
        np.fill_diagonal(A, A.diagonal())
        deg = A.sum(0) + A.sum(1) - 2 * A.diagonal()
        if (deg > 0).all() and abs(A.sum() / S ** 2 - Ct) < 0.02:
            return n, A


n, A = niche_web()
B = A.copy()
np.fill_diagonal(B, False)
k = B.sum(1)
Qm = np.where(k[:, None] > 0, B / np.maximum(k, 1)[:, None], 0.0)
TL = np.linalg.solve(np.eye(S) - Qm, np.ones(S))

pa = C.axes_at(ax, (2.6, 1.9, 13.0, 9.4))
for i in range(S):
    for j in range(S):
        if B[i, j]:
            pa.plot([n[j], n[i]], [TL[j], TL[i]], color=P.muted(), lw=0.5, alpha=0.6, zorder=1)
basal = k == 0
top = B.sum(0) == 0
cols = np.where(basal, Q.line_color("plant"), np.where(top, Q.line_color("negative"), Q.line_color("dna")))
pa.scatter(n, TL, s=30, c=list(cols), edgecolors=P.ink(), linewidths=0.4, zorder=3)
for lab, tok, msk in [("basal", "plant", basal), ("intermediate", "dna", ~basal & ~top), ("top", "negative", top)]:
    if not msk.any():
        continue
    pa.scatter([], [], s=30, c=Q.line_color(tok), edgecolors=P.ink(), linewidths=0.4, label=lab)
pa.set_xlim(-0.02, 1.02)
pa.set_ylim(0.7, TL.max() + 0.4)
C.style_axes(pa, "niche value", "trophic level (prey-averaged)")
pa.legend(frameon=False, fontsize=FS["tiny"], labelcolor=P.ink(), loc="upper left")
bio.panel(ax, "A", (0.5, 12.6))
bio.label(ax, (2.6, 12.2), f"Niche-model web: S = {S}, L = {int(A.sum())}, C = L/S^2 = {A.sum() / S**2:.3f}",
          size="small", bold=True, ha="left")

pb = C.axes_at(ax, (19.6, 1.9, 9.4, 9.4))
yy, xx = np.nonzero(A)
pb.scatter(xx, yy, marker="s", s=14, color=Q.line_color("dna"), lw=0)
pb.set_xlim(-0.5, S - 0.5)
pb.set_ylim(S - 0.5, -0.5)
pb.set_xticks([0, 10, 20, 29])
pb.set_yticks([0, 10, 20, 29])
C.style_axes(pb, "resource (ordered by niche value)", "consumer (ordered by niche value)", box=True)
bio.panel(ax, "B", (17.6, 12.6))
bio.label(ax, (19.6, 12.2), "Feeding matrix: interval diets", size="small", bold=True, ha="left")
